{
  "title": "时间循环：钥匙与钟表",
  "scene": "你被困在一个时间循环中，每天早上8点都会醒来，周围是一个老旧的图书馆。书架上摆放着各种古籍，其中一本《时间之书》引起了你的注意。你发现图书馆中央有一个巨大的钟，指针停在了12点，似乎无法移动。书架边缘放着一把看似破旧但又手感不错的钥匙。",
  "goal": "找到逃脱图书馆的方法",
  "clue": "《时间之书》和钟表",
  "choices": [
    {"id": "A", "text": "尝试用钥匙打开图书馆的门", "outcome": "钥匙被卡住，无法打开门。你意识到钥匙可能不适合这个锁。", "result": "fail", "next": "retry"},
    {"id": "B", "text": "阅读《时间之书》，试图找到线索", "outcome": "书中提到需要调整钟表的时间，才能解锁图书馆。你检查钟表，发现它应该指向8点，但指针被卡在12点。", "result": "partial", "next": "retry"},
    {"id": "C", "text": "试着移动钟表，看能否让指针跑起来", "outcome": "你发现钟表的发条可以手动上紧，一旦上紧，指针开始缓慢前进。当指针指向8点时，图书馆的门缓缓打开了。", "result": "success", "next": "next_level"}
  ]
}
